scriptdefs
= SlateportCity_OceanicMuseum_1F_EventScript_PayEntranceFeeRight
lockall
applymovement LOCALID_PLAYER Common_Movement_WalkInPlaceFasterRight
waitmovement 0
goto SlateportCity_OceanicMuseum_1F_EventScript_PayEntranceFee
end
= SlateportCity_OceanicMuseum_1F_EventScript_PayEntranceFee
showmoneybox 0 0
msgboxyesno	Welcome to the OCEANIC MUSEUM.The entrance fee is ¥50. Would you like to enter?
goto_if_eq VAR_RESULT YES SlateportCity_OceanicMuseum_1F_EventScript_CheckMoneyForFee
closemessage
hidemoneybox
applymovement LOCALID_PLAYER SlateportCity_OceanicMuseum_1F_Movement_PushPlayerBackFromCounter
waitmovement 0
releaseall
end
= SlateportCity_OceanicMuseum_1F_EventScript_CheckMoneyForFee
checkmoney 50
goto_if_eq VAR_RESULT FALSE SlateportCity_OceanicMuseum_1F_EventScript_NotEnoughMoney
playse SE_SHOP
removemoney 50
updatemoneybox
msgbox	Please enjoy yourself.
setvar VAR_SLATEPORT_MUSEUM_1F_STATE 1
hidemoneybox
releaseall
end
= SlateportCity_OceanicMuseum_1F_EventScript_NotEnoughMoney
goto_if_unset FLAG_DELIVERED_DEVON_GOODS SlateportCity_OceanicMuseum_1F_EventScript_AllowEntranceAnyway
msgbox	Oh? I'm sorry, but you don't seem to have enough money.
closemessage
hidemoneybox
applymovement LOCALID_PLAYER SlateportCity_OceanicMuseum_1F_Movement_PushPlayerBackFromCounter
waitmovement 0
releaseall
end
= SlateportCity_OceanicMuseum_1F_EventScript_AllowEntranceAnyway
msgbox	Oh? You're with that group that went in earlier?You're the only one who's late. You'd better go catch up to them!
setvar VAR_SLATEPORT_MUSEUM_1F_STATE 1
hidemoneybox
releaseall
end
= SlateportCity_OceanicMuseum_1F_EventScript_PayEntranceFeeLeft
lockall
applymovement LOCALID_PLAYER Common_Movement_WalkInPlaceFasterLeft
waitmovement 0
goto SlateportCity_OceanicMuseum_1F_EventScript_PayEntranceFee
end
= SlateportCity_OceanicMuseum_1F_EventScript_Reporter
lock
faceplayer
setvar VAR_0x8005 TVSHOW_RECENT_HAPPENINGS
special InterviewBefore
goto_if_eq VAR_RESULT TRUE SlateportCity_OceanicMuseum_1F_EventScript_AlreadyInterviewed
copyvar VAR_0x8009 VAR_0x8006
goto_if_set FLAG_OCEANIC_MUSEUM_MET_REPORTER SlateportCity_OceanicMuseum_1F_EventScript_RequestInterviewShort
setflag FLAG_OCEANIC_MUSEUM_MET_REPORTER
msgboxyesno	Oh? Do you perhaps like POKéMON?I'm on assignment with the TV network.I'm gathering stories on POKéMON and TRAINERS that occurred recently.If you don't mind, could you tell me something about yourself?
goto_if_eq VAR_RESULT YES SlateportCity_OceanicMuseum_1F_EventScript_AcceptInterview
goto_if_eq VAR_RESULT NO SlateportCity_OceanicMuseum_1F_EventScript_DeclineInterview
end
= SlateportCity_OceanicMuseum_1F_EventScript_DeclineInterview
msgbox	Oh, I see…Well, if you do have an interesting story to tell, please let me know.
release
end
= SlateportCity_OceanicMuseum_1F_EventScript_AcceptInterview
msgbox	Oh, you will? Thank you!Then, please, tell me anything of interest that you experienced recently involving POKéMON.
setvar VAR_0x8004 EASY_CHAT_TYPE_INTERVIEW
copyvar VAR_0x8005 VAR_0x8009
setvar VAR_0x8006 EASY_CHAT_PERSON_REPORTER_MALE
call Common_ShowEasyChatScreen
lock
faceplayer
goto_if_eq VAR_RESULT 1 SlateportCity_OceanicMuseum_1F_EventScript_SubmitResponse
goto_if_eq VAR_RESULT 0 SlateportCity_OceanicMuseum_1F_EventScript_DeclineInterview
end
= SlateportCity_OceanicMuseum_1F_EventScript_SubmitResponse
msgbox	Oh, what an uplifting story!I'll be sure to get your story told on television.It should be aired sometime, I think, so please look forward to it.
setvar VAR_0x8005 TVSHOW_RECENT_HAPPENINGS
goto Interview_EventScript_EndInterview
end
= Interview_EventScript_EndInterview
special InterviewAfter
incrementgamestat GAME_STAT_GOT_INTERVIEWED
release
end
@ Shares reporter object with TVSHOW_PKMN_FAN_CLUB_OPINIONS
goto SlateportCity_PokemonFanClub_EventScript_ReporterNoNickname
= SlateportCity_PokemonFanClub_EventScript_ReporterNoNickname
setvar VAR_0x8005 TVSHOW_FAN_CLUB_LETTER
special InterviewBefore
goto_if_eq VAR_RESULT TRUE SlateportCity_PokemonFanClub_EventScript_AlreadyInterviewed2
copyvar VAR_0x8009 VAR_0x8006
msgboxyesno	Hi, you seem to be very close to your .Do you know what? I'm a TV reporter.I travel around interviewing people about POKéMON.I'm wondering if you'd be willing to tell me a little about your ?
goto_if_eq VAR_RESULT YES SlateportCity_PokemonFanClub_EventScript_AcceptInterview2
goto_if_eq VAR_RESULT NO SlateportCity_PokemonFanClub_EventScript_DeclineInterview2
end
= SlateportCity_PokemonFanClub_EventScript_DeclineInterview2
msgbox	Oh, okay…Well, if you get the urge to tell me about POKéMON, I'll be here!
release
end
= SlateportCity_PokemonFanClub_EventScript_AcceptInterview2
msgbox	Wow, thank you!Okay, then, please tell me anything you'd like about your .
setvar VAR_0x8004 EASY_CHAT_TYPE_INTERVIEW
copyvar VAR_0x8005 VAR_0x8009
setvar VAR_0x8006 EASY_CHAT_PERSON_REPORTER_FEMALE
call Common_ShowEasyChatScreen
lock
faceplayer
goto_if_eq VAR_RESULT 1 SlateportCity_PokemonFanClub_EventScript_SubmitResponse2
goto_if_eq VAR_RESULT 0 SlateportCity_PokemonFanClub_EventScript_DeclineInterview2
end
= SlateportCity_PokemonFanClub_EventScript_SubmitResponse2
msgbox	Wow… That's an interesting account.You really are tight with , aren't you?I get the feeling that your account will make a great TV story.I promise that I'll turn this into an entertaining show. Keep your eyes out for it.Okay, that's all. Bye-bye!
setvar VAR_0x8005 TVSHOW_FAN_CLUB_LETTER
goto Interview_EventScript_EndInterview
end
= SlateportCity_PokemonFanClub_EventScript_AlreadyInterviewed2
msgbox	I enjoy this job--you get to learn about POKéMON by doing interviews.
release
end
= SlateportCity_OceanicMuseum_1F_EventScript_RequestInterviewShort
msgboxyesno	I'm gathering stories on POKéMON and TRAINERS that occurred recently.If you don't mind, could you tell me something about yourself?
goto_if_eq VAR_RESULT YES SlateportCity_OceanicMuseum_1F_EventScript_AcceptInterview
goto_if_eq VAR_RESULT NO SlateportCity_OceanicMuseum_1F_EventScript_DeclineInterview
end
= SlateportCity_OceanicMuseum_1F_EventScript_AlreadyInterviewed
msgbox	Hmmm… I've got a good story for a TV program.I'd better write it up in a hurry!
release
end
= SlateportCity_OceanicMuseum_1F_EventScript_FamiliarGrunt
lock
faceplayer
delay 8
playse SE_PIN
applymovement LOCALID_OCEANIC_MUSEUM_FAMILIAR_GRUNT Common_Movement_ExclamationMark
waitmovement 0
applymovement LOCALID_OCEANIC_MUSEUM_FAMILIAR_GRUNT Common_Movement_Delay48
waitmovement 0
msgbox	Aiyeeeh! What are you doing here?Me? I'm the TEAM AQUA member you thumped before, remember? Back in RUSTURF TUNNEL?Here, take this! You have to forgive me!
giveitem ITEM_TM_THIEF
goto_if_eq VAR_RESULT 0 SlateportCity_OceanicMuseum_1F_EventScript_NoRoomForThief
setflag FLAG_RECEIVED_TM_THIEF
msgbox	That TM, it suits you more than it does me.Hope I never see you again! Wahahaha!
closemessage
goto_if_eq VAR_FACING DIR_NORTH SlateportCity_OceanicMuseum_1F_EventScript_FamiliarGruntExitNorth
goto_if_eq VAR_FACING DIR_SOUTH SlateportCity_OceanicMuseum_1F_EventScript_FamiliarGruntExitSouth
goto_if_eq VAR_FACING DIR_WEST SlateportCity_OceanicMuseum_1F_EventScript_FamiliarGruntExitWestEast
goto_if_eq VAR_FACING DIR_EAST SlateportCity_OceanicMuseum_1F_EventScript_FamiliarGruntExitWestEast
end
= SlateportCity_OceanicMuseum_1F_EventScript_FamiliarGruntExitWestEast
applymovement LOCALID_PLAYER SlateportCity_OceanicMuseum_1F_Movement_PlayerWatchGruntExitWestEast
applymovement LOCALID_OCEANIC_MUSEUM_FAMILIAR_GRUNT SlateportCity_OceanicMuseum_1F_Movement_FamiliarGruntExit
waitmovement 0
goto SlateportCity_OceanicMuseum_1F_EventScript_FamiliarGruntExited
end
= SlateportCity_OceanicMuseum_1F_EventScript_FamiliarGruntExited
setflag FLAG_HIDE_SLATEPORT_CITY_OCEANIC_MUSEUM_FAMILIAR_AQUA_GRUNT
playse SE_EXIT
removeobject LOCALID_OCEANIC_MUSEUM_FAMILIAR_GRUNT
release
end
= SlateportCity_OceanicMuseum_1F_EventScript_FamiliarGruntExitSouth
applymovement LOCALID_OCEANIC_MUSEUM_FAMILIAR_GRUNT SlateportCity_OceanicMuseum_1F_Movement_FamiliarGruntExit
waitmovement 0
goto SlateportCity_OceanicMuseum_1F_EventScript_FamiliarGruntExited
end
= SlateportCity_OceanicMuseum_1F_EventScript_FamiliarGruntExitNorth
applymovement LOCALID_PLAYER SlateportCity_OceanicMuseum_1F_Movement_PlayerWatchGruntExitNorth
applymovement LOCALID_OCEANIC_MUSEUM_FAMILIAR_GRUNT SlateportCity_OceanicMuseum_1F_Movement_FamiliarGruntExitNorth
waitmovement 0
goto SlateportCity_OceanicMuseum_1F_EventScript_FamiliarGruntExited
end
